create function public.is_board_member(p_board_id bigint, p_role text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.board_members m
    where m.board_id = p_board_id and m.user_id = auth.uid() and m.role = p_role
  );
$$;

create function public.board_is_active(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.boards b where b.id = p_board_id and not b.is_archived
  );
$$;

create function public.can_edit_card(p_card_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.cards c where c.id = p_card_id and public.board_is_active(c.board_id) and public.is_board_member(c.board_id, 'editor')
  );
$$;

create function public.can_create_card(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.board_members m where m.board_id = p_board_id and m.user_id = auth.uid() and m.role = 'editor' and not exists (select 1 from public.boards b where b.id = p_board_id and b.is_archived)
  );
$$;

create function public.can_move_card(p_card_id bigint, p_new_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.cards c where c.id = p_card_id and public.board_is_active(c.board_id) and public.is_board_member(c.board_id, 'editor') and public.is_board_member(p_new_board_id, 'editor') and not exists (select 1 from public.boards b where b.id = p_new_board_id and b.is_archived)
  );
$$;

create function public.enforce_card_column(p_card_id bigint, p_column_name text)
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if new.id is distinct from old.id or new.board_id is distinct from old.board_id then
    raise exception 'Cannot move card';
  end if;
  if new.assignee_id is distinct from old.assignee_id then
    raise exception 'Cannot change assignee';
  end if;
  if new.column_name not in ('todo', 'doing', 'done') then
    raise exception 'Invalid column name';
  end if;
  if not public.can_edit_card(old.id) then
    raise exception 'Card cannot be edited';
  end if;
  if not exists (select 1 from public.board_members m where m.board_id = new.board_id and m.user_id = auth.uid() and m.role = 'editor') then
    raise exception 'Not an editor on this board';
  end if;
  return new;
end;
$$;

