```sql
alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create function public.is_friend(p_user uuid, p_other uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.friendships f
    where (f.requester_id = p_user and f.addressee_id = p_other)
       or (f.requester_id = p_other and f.addressee_id = p_user)
      and f.status = 'accepted'
  );
$$;

create function public.post_audience_accessible(p_post_audience text, p_post_author uuid, p_viewer uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select
    p_post_audience = 'public'
    or p_viewer is null
    or p_post_author = p_viewer
    or public.is_friend(p_post_author, p_viewer);
$$;

create function public.enforce_friendship_update()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.requester_id is distinct from old.requester_id
     or new.addressee_id is distinct from old.addressee_id then
    raise exception 'friendship endpoints cannot be changed';
  end if;

  if old.status <> 'pending' then
    raise exception 'only pending requests can be accepted';
  end if;

  if new.status <> 'accepted' then
    raise exception 'only pending requests can be accepted';
  end if;

  if new.requester_id = new.addressee_id then
    raise exception 'cannot accept your own request';
  end if;

  return new;
end;
$$;

create trigger friendships_enforce_update
before update on public.friendships
for each row execute function public.enforce_friendship_update();

create policy "posts_select"
on public.posts
for select
to anon, authenticated
using (public.post_audience_accessible(audience, author_id, auth.uid()));

create policy "posts_insert"
on public.posts
for insert
to authenticated
with check (author_id = auth.uid());

create policy "posts_update"
on public.posts
for update
to authenticated
using (author_id = auth.uid())
with check (author_id = auth.uid());

create policy "posts_delete"
on public.posts
for delete
to authenticated
using (author_id = auth.uid());

create policy "friendships_select"
on public.friendships
for select
to authenticated
using (requester_id = auth.uid() or addressee_id = auth.uid());

create policy "friendships_insert"
on public.friendships
for insert
to authenticated
with check (requester_id = auth.uid() and status = 'pending');

create policy "friendships_update"
on public.friendships
for update
to authenticated
using (requester_id = auth.uid() or addressee_id = auth.uid())
with check (requester_id = auth.uid() or addressee_id = auth.uid());

revoke all on public.friendships from anon;
revoke all on public.posts from anon;

grant select on public.posts to anon;

grant select, insert, update, delete on public.posts to authenticated;
grant select, insert, update on public.friendships to authenticated;

grant all on public.friendships to service_role;
grant all on public.posts to service_role;

grant usage, select on all sequences in schema public to authenticated, service_role;

grant execute on function public.is_friend to authenticated, service_role;
grant execute on function public.post_audience_accessible to authenticated, service_role;
