as $$
  select exists (
    select 1 from public.friendships f
    where (f.requester_id = p_user and f.addressee_id = p_other and f.status = 'accepted')
       or (f.requester_id = p_other and f.addressee_id = p_user and f.status = 'accepted')
  );
$$;

create function public.post_audience_visible(p_post_audience text, p_post_author uuid, p_viewer uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select p_post_audience = 'public'
         or p_post_author = p_viewer
         or (p_post_audience = 'friends' and public.is_friend(p_viewer, p_post_author));
$$;

create function public.prevent_friendship_changes()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.role() = 'service_role' or current_user = 'service_role' then
    return new;
  end if;
  if new.requester_id <> old.requester_id or new.addressee_id <> old.addressee_id then
    raise exception 'friendship participants cannot be changed';
  end if;
  if new.status <> 'accepted' then
    raise exception 'friendship status can only be changed to accepted';
  end if;
  if old.status <> 'pending' then
    raise exception 'only pending requests can be accepted';
  end if;
  if old.requester_id = new.requester_id then
    raise exception 'requester cannot accept their own request';
  end if;
  return new;
end;
$$;

create trigger friendships_prevent_changes
before update on public.friendships
for each row execute function public.prevent_friendship_changes();

